-- Targeted, version-guarded dialogue correction and approved flag rule addition.
-- Does not modify quest conditions, progress, rewards, player saves or schema.
BEGIN;
DO $publish$
DECLARE
 oldrow public."GameDataCurrent"%ROWTYPE;
 edits jsonb := '[{"DialogueID":"xi_secret_1_offer_3","QuestID":"xi_secret_1","before":"先帶指定魔攻武器給我。要能交付的，我會拆開研究。","Text":"先帶 1 把聚魂法杖給我。要能交付的，交出去就不會退還；我會拆開研究。"},{"DialogueID":"xi_secret_2_offer_0","QuestID":"xi_secret_2","before":"接著是兩種指定王關寶石，各一顆。","Text":"接著交給我地獄魔人寶石、地獄犬寶石各 1 顆。兩種都要，別拿兩顆一樣的來考驗我的耐心。"},{"DialogueID":"xi_secret_3_offer_0","QuestID":"xi_secret_3","before":"去討伐個幾隻指定魔法系怪物。","Text":"接下委託後，討伐龍紋祭司 5 隻。這次除了打贏，也記一下牠們施法的節奏。"},{"DialogueID":"xi_secret_4_offer_0","QuestID":"xi_secret_4","before":"這次研究需要指定魔攻武器，拿來當作參考。","Text":"這次交給我 1 本不死王秘典，當作研究材料。交付後會消耗，先把你自己要用的留好。"},{"DialogueID":"xi_secret_4_offer_1","QuestID":"xi_secret_4","before":"終於不用拆了。","Text":"連書都收走？我以為這次只是借妳看。"},{"DialogueID":"xi_secret_4_offer_2","QuestID":"xi_secret_4","before":"你很失望嗎？我可以調整。","Text":"我會做很多筆記。寫完以後，原作者可能也認不出來。"},{"DialogueID":"xi_secret_4_offer_3","QuestID":"xi_secret_4","before":"完全沒有。","Text":"那我先確認沒把常用的那本交出去。"},{"DialogueID":"xi_secret_4_offer_4","QuestID":"xi_secret_4","before":"實際體會一次，會比較清楚魔力經過哪裡。","Text":"很好。研究要動腦，交材料也一樣。"},{"DialogueID":"xi_secret_4_complete_0","QuestID":"xi_secret_4","before":"做得不錯。手給我，看看有沒有燙傷。","Text":"秘典收到了。這幾頁的魔力痕跡正好能用來對照。"},{"DialogueID":"xi_secret_4_complete_1","QuestID":"xi_secret_4","before":"……我只是希望最後一課能準時開始。","Text":"……不是我迫不及待，只是最後一課最好準時開始。"},{"DialogueID":"xi_secret_5_offer_0","QuestID":"xi_secret_5","before":"最後，擊敗指定BOSS 2次。","Text":"最後，接下委託後擊敗深淵海皇・涅普提斯 2 次。"},{"DialogueID":"xi_secret_5_offer_2","QuestID":"xi_secret_5","before":"第一次可能靠運氣，第二次可能剛好。第三次，你應該能告訴我自己怎麼贏的。","Text":"第一次算，但第二次要讓我看出你知道自己怎麼贏的。不能每次都把答案寫成運氣。"},{"DialogueID":"xi_secret_5_offer_3","QuestID":"xi_secret_5","before":"當然，你也可以連續幸運三次。我會稍微嫉妒。","Text":"當然，你也可以連續幸運兩次。我會稍微嫉妒。"},{"DialogueID":"kazama_secret_1_offer_5","QuestID":"kazama_secret_1","before":"先帶指定物攻武器過來，交給我當教具。我們從重心和出手開始。","Text":"先交給我 1 把處刑巨斧當教具，交付後不會退還。我們從重心和出手開始。"},{"DialogueID":"kazama_secret_2_offer_0","QuestID":"kazama_secret_2","before":"去討伐個幾隻指定近戰怪物，留意自己什麼時候開始急。","Text":"接下委託後，討伐零域守衛 5 隻。留意自己什麼時候開始急。"},{"DialogueID":"kazama_secret_3_offer_0","QuestID":"kazama_secret_3","before":"任一\"武器\"成功強化三次。","Text":"接下委託後，武器成功強化累計 3 次。不一定要同一把，失敗不算，別把它哭成成功。"},{"DialogueID":"kazama_secret_5_offer_0","QuestID":"kazama_secret_5","before":"最後，擊敗指定BOSS三次，活著回來找我。","Text":"最後，接下委託後擊敗龍城女帝 3 次，活著回來找我。"},{"DialogueID":"yexian_secret_1_offer_7","QuestID":"yexian_secret_1","before":"帶指定物攻、魔攻裝備各一件，選你願意交付的。","Text":"交給我深淵珊瑚刃、墜星軍刀各 1 把。兩種都要，交付後會消耗，選你願意交出的。"},{"DialogueID":"yexian_secret_2_offer_0","QuestID":"yexian_secret_2","before":"下一步，指定寶石2顆。","Text":"下一步，交付龍王寶石、不死王寶石各 1 顆。不是任選兩顆。"},{"DialogueID":"yexian_secret_3_offer_0","QuestID":"yexian_secret_3","before":"指定近戰、魔法系怪物各5隻。觀察牠們怎麼抓距離，什麼時候追、什麼時候退。","Text":"接下委託後，討伐星軌處刑者、重力巨神各 5 隻。觀察牠們怎麼抓距離，什麼時候追、什麼時候退。"},{"DialogueID":"yexian_secret_4_offer_0","QuestID":"yexian_secret_4","before":"完成一次裝備強化，再鑲嵌一顆寶石。有不清楚的先問。","Text":"接下委託後，嘗試裝備強化 1 次，再完成寶石鑲嵌 1 次。強化不要求成功，也不限制部位；有不清楚的先問。"},{"DialogueID":"yexian_secret_5_offer_0","QuestID":"yexian_secret_5","before":"最後，開始兩位指定BOSS挑戰。","Text":"最後，接下委託後擊敗龍城女帝 5 次、星蝕觀測者・阿斯特拉 1 次。兩個目標都要完成。"},{"DialogueID":"yexian_secret_5_complete_0","QuestID":"yexian_secret_5","before":"第二次那一步，退得不錯。","Text":"女帝那幾場的步伐穩多了，對上觀測者也沒有亂掉。"},{"DialogueID":"lily_enhance_offer_5","QuestID":"lily_enhance","before":"好啦，不鬧你。這五顆強化石拿去，先試著強化一次\"武器\"。","Text":"好啦，不鬧你。接受委託後這五顆強化石拿去，試著強化任一把武器 1 次；成功或失敗都算，別跑去強化帽子。"},{"DialogueID":"lily_socket_offer_4","QuestID":"lily_socket","before":"鑲上去能加十點HP。去鑲嵌介面，挑好位置再放。","Text":"鑲上去能加十點 HP。接受委託後，替任一件裝備鑲嵌寶石 1 次就算完成；這顆拿去用，別拿來當糖吃。"},{"DialogueID":"xi_secret_1_progress_0","QuestID":"xi_secret_1","before":"缺材料就找材料，缺休息就去休息。弄錯順序通常比較花時間。","Text":"交付聚魂法杖 1 把。我等材料，不是在等你跟貓聊天。"},{"DialogueID":"xi_secret_2_progress_0","QuestID":"xi_secret_2","before":"缺材料就找材料，缺休息就去休息。弄錯順序通常比較花時間。","Text":"交付地獄魔人寶石、地獄犬寶石各 1 顆。我等材料，不是在等你跟貓聊天。"},{"DialogueID":"xi_secret_3_progress_0","QuestID":"xi_secret_3","before":"缺材料就找材料，缺休息就去休息。弄錯順序通常比較花時間。","Text":"接取後討伐龍紋祭司 5 隻。我等材料，不是在等你跟貓聊天。"},{"DialogueID":"xi_secret_4_progress_0","QuestID":"xi_secret_4","before":"缺材料就找材料，缺休息就去休息。弄錯順序通常比較花時間。","Text":"交付不死王秘典 1 本。我等材料，不是在等你跟貓聊天。"},{"DialogueID":"xi_secret_5_progress_0","QuestID":"xi_secret_5","before":"缺材料就找材料，缺休息就去休息。弄錯順序通常比較花時間。","Text":"接取後擊敗深淵海皇・涅普提斯 2 次。我等材料，不是在等你跟貓聊天。"},{"DialogueID":"kazama_secret_1_progress_0","QuestID":"kazama_secret_1","before":"卡在哪裡？說來聽聽。你不講，我就只能猜你想來陪我聊天。","Text":"交付處刑巨斧 1 把。先看清楚，別練得很認真，項目卻不對！"},{"DialogueID":"kazama_secret_2_progress_0","QuestID":"kazama_secret_2","before":"卡在哪裡？說來聽聽。你不講，我就只能猜你想來陪我聊天。","Text":"接取後討伐零域守衛 5 隻。先看清楚，別練得很認真，項目卻不對！"},{"DialogueID":"kazama_secret_3_progress_0","QuestID":"kazama_secret_3","before":"卡在哪裡？說來聽聽。你不講，我就只能猜你想來陪我聊天。","Text":"接取後武器成功強化累計 3 次。先看清楚，別練得很認真，項目卻不對！"},{"DialogueID":"kazama_secret_4_progress_0","QuestID":"kazama_secret_4","before":"卡在哪裡？說來聽聽。你不講，我就只能猜你想來陪我聊天。","Text":"完成競技場對戰結算 3 次，不限勝負；先前已累積的任務進度保留。先看清楚，別練得很認真，項目卻不對！"},{"DialogueID":"kazama_secret_5_progress_0","QuestID":"kazama_secret_5","before":"卡在哪裡？說來聽聽。你不講，我就只能猜你想來陪我聊天。","Text":"接取後擊敗龍城女帝 3 次。先看清楚，別練得很認真，項目卻不對！"},{"DialogueID":"yexian_secret_1_progress_0","QuestID":"yexian_secret_1","before":"卡住就說卡在哪裡。點頭裝懂，通常要多走一趟。","Text":"交付深淵珊瑚刃、墜星軍刀各 1 把。一項一項來，別急著證明自己看得很快。"},{"DialogueID":"yexian_secret_2_progress_0","QuestID":"yexian_secret_2","before":"卡住就說卡在哪裡。點頭裝懂，通常要多走一趟。","Text":"交付龍王寶石、不死王寶石各 1 顆。一項一項來，別急著證明自己看得很快。"},{"DialogueID":"yexian_secret_3_progress_0","QuestID":"yexian_secret_3","before":"卡住就說卡在哪裡。點頭裝懂，通常要多走一趟。","Text":"接取後討伐星軌處刑者、重力巨神各 5 隻。一項一項來，別急著證明自己看得很快。"},{"DialogueID":"yexian_secret_4_progress_0","QuestID":"yexian_secret_4","before":"卡住就說卡在哪裡。點頭裝懂，通常要多走一趟。","Text":"接取後嘗試任意裝備強化 1 次、完成寶石鑲嵌 1 次；強化不限成功。一項一項來，別急著證明自己看得很快。"},{"DialogueID":"yexian_secret_5_progress_0","QuestID":"yexian_secret_5","before":"卡住就說卡在哪裡。點頭裝懂，通常要多走一趟。","Text":"接取後擊敗龍城女帝 5 次、星蝕觀測者・阿斯特拉 1 次。一項一項來，別急著證明自己看得很快。"},{"DialogueID":"lily_partner_progress_0","QuestID":"lily_partner","before":"有哪裡不懂就問。站在這裡看我，不會自己完成喔。","Text":"通關主線第 5 層；已經通過也算。記不住就看任務目標，別把我當會走路的記事本。"},{"DialogueID":"lily_enhance_progress_0","QuestID":"lily_enhance","before":"有哪裡不懂就問。站在這裡看我，不會自己完成喔。","Text":"接取後嘗試武器強化 1 次，成功或失敗都算。記不住就看任務目標，別把我當會走路的記事本。"},{"DialogueID":"lily_socket_progress_0","QuestID":"lily_socket","before":"有哪裡不懂就問。站在這裡看我，不會自己完成喔。","Text":"接取後替任意裝備鑲嵌寶石 1 次。記不住就看任務目標，別把我當會走路的記事本。"},{"DialogueID":"xi_research_progress_0","QuestID":"xi_research","before":"缺材料就找材料，缺休息就去休息。弄錯順序通常比較花時間。","Text":"交付天然手環、天然戒指各 1 件。我等材料，不是在等你跟貓聊天。"}]'::jsonb;
 flag_rules jsonb := '[{"Key":"FlagScoreMinutes","Value":180,"Description":"每面旗幟存續計分週期（分鐘）"},{"Key":"FlagScorePoints","Value":1,"Description":"每面旗幟每期積分"},{"Key":"RemoveEnemyFlagPoints","Value":3,"Description":"拔除敵方旗幟積分"}]'::jsonb;
 updated_dialogues jsonb;
 updated_config jsonb;
 next_package jsonb;
 stamp timestamptz := clock_timestamp();
 next_version text;
BEGIN
 SELECT * INTO STRICT oldrow FROM public."GameDataCurrent" WHERE channel='production' FOR UPDATE;
 IF oldrow.version <> '20261115-214526-5e77d066' THEN RAISE EXCEPTION 'PLANNING_VERSION_CHANGED'; END IF;
 IF oldrow.data_json->'data'->'QuestObjectives' <> '[{"Slot":"","Type":"dialogue","Label":"","__row":2,"QuestID":"lily_ready","Quantity":1,"TargetID":"","MinEnhance":0,"ObjectiveID":"lily_ready_1"},{"Slot":"","Type":"main_clear","Label":"","__row":3,"QuestID":"lily_partner","Quantity":1,"TargetID":5,"MinEnhance":0,"ObjectiveID":"lily_partner_1"},{"Slot":"weapon","Type":"enhance","Label":"","__row":4,"QuestID":"lily_enhance","Quantity":1,"TargetID":"","MinEnhance":0,"ObjectiveID":"lily_enhance_1"},{"Slot":"","Type":"socket","Label":"","__row":5,"QuestID":"lily_socket","Quantity":1,"TargetID":"","MinEnhance":0,"ObjectiveID":"lily_socket_1"},{"Slot":"","Type":"deliver_equipment","Label":"天然手環","__row":6,"QuestID":"xi_research","Quantity":1,"TargetID":"naturalBracelet","MinEnhance":0,"ObjectiveID":"xi_research_1"},{"Slot":"","Type":"deliver_equipment","Label":"天然戒指","__row":7,"QuestID":"xi_research","Quantity":1,"TargetID":"naturalRing","MinEnhance":0,"ObjectiveID":"xi_research_2"},{"Slot":"","Type":"dialogue","Label":"","__row":8,"QuestID":"kazama_status","Quantity":1,"TargetID":"","MinEnhance":0,"ObjectiveID":"kazama_status_1"},{"Slot":"weapon","Type":"deliver_equipment","Label":"聚魂法杖","__row":9,"QuestID":"xi_secret_1","Quantity":1,"TargetID":"soulStaff","MinEnhance":0,"ObjectiveID":"xi_secret_1_1"},{"Slot":"","Type":"deliver_gem","Label":"地獄魔人寶石","__row":10,"QuestID":"xi_secret_2","Quantity":1,"TargetID":"hellDemon","MinEnhance":0,"ObjectiveID":"xi_secret_2_1"},{"Slot":"","Type":"deliver_gem","Label":"地獄犬寶石","__row":11,"QuestID":"xi_secret_2","Quantity":1,"TargetID":"hellHound","MinEnhance":0,"ObjectiveID":"xi_secret_2_2"},{"Slot":"","Type":"kill","Label":"龍紋祭司","__row":12,"QuestID":"xi_secret_3","Quantity":5,"TargetID":"dragonPriest","MinEnhance":0,"ObjectiveID":"xi_secret_3_1"},{"Slot":"","Type":"deliver_equipment","Label":"不死王秘典","__row":13,"QuestID":"xi_secret_4","Quantity":1,"TargetID":"azraelGrimoire","MinEnhance":0,"ObjectiveID":"xi_secret_4_1"},{"Slot":"","Type":"kill","Label":"深淵海皇・涅普提斯","__row":14,"QuestID":"xi_secret_5","Quantity":2,"TargetID":"boss70","MinEnhance":0,"ObjectiveID":"xi_secret_5_1"},{"Slot":"weapon","Type":"deliver_equipment","Label":"處刑巨斧","__row":15,"QuestID":"kazama_secret_1","Quantity":1,"TargetID":"executionerAxe","MinEnhance":0,"ObjectiveID":"kazama_secret_1_1"},{"Slot":"","Type":"kill","Label":"零域守衛","__row":16,"QuestID":"kazama_secret_2","Quantity":5,"TargetID":"nullGuard","MinEnhance":0,"ObjectiveID":"kazama_secret_2_1"},{"Slot":"weapon","Type":"enhance_success","Label":"","__row":17,"QuestID":"kazama_secret_3","Quantity":3,"TargetID":"","MinEnhance":0,"ObjectiveID":"kazama_secret_3_1"},{"Slot":"","Type":"battle","Label":"完成競技場對戰結算","__row":18,"QuestID":"kazama_secret_4","Quantity":3,"TargetID":"arena","MinEnhance":0,"ObjectiveID":"kazama_secret_4_1"},{"Slot":"","Type":"kill","Label":"龍城女帝","__row":19,"QuestID":"kazama_secret_5","Quantity":3,"TargetID":"boss50","MinEnhance":0,"ObjectiveID":"kazama_secret_5_1"},{"Slot":"","Type":"deliver_equipment","Label":"深淵珊瑚刃","__row":20,"QuestID":"yexian_secret_1","Quantity":1,"TargetID":"abyssCoralBlade","MinEnhance":0,"ObjectiveID":"yexian_secret_1_1"},{"Slot":"","Type":"deliver_equipment","Label":"墜星軍刀","__row":21,"QuestID":"yexian_secret_1","Quantity":1,"TargetID":"starfallSaber","MinEnhance":0,"ObjectiveID":"yexian_secret_1_2"},{"Slot":"","Type":"deliver_gem","Label":"龍王寶石","__row":22,"QuestID":"yexian_secret_2","Quantity":1,"TargetID":"dragonKing","MinEnhance":0,"ObjectiveID":"yexian_secret_2_1"},{"Slot":"","Type":"deliver_gem","Label":"不死王寶石","__row":23,"QuestID":"yexian_secret_2","Quantity":1,"TargetID":"undeadKing","MinEnhance":0,"ObjectiveID":"yexian_secret_2_2"},{"Slot":"","Type":"kill","Label":"星軌處刑者","__row":24,"QuestID":"yexian_secret_3","Quantity":5,"TargetID":"astralExecutioner","MinEnhance":0,"ObjectiveID":"yexian_secret_3_1"},{"Slot":"","Type":"kill","Label":"重力巨神","__row":25,"QuestID":"yexian_secret_3","Quantity":5,"TargetID":"gravityTitan","MinEnhance":0,"ObjectiveID":"yexian_secret_3_2"},{"Slot":"","Type":"enhance","Label":"","__row":26,"QuestID":"yexian_secret_4","Quantity":1,"TargetID":"","MinEnhance":0,"ObjectiveID":"yexian_secret_4_1"},{"Slot":"","Type":"socket","Label":"","__row":27,"QuestID":"yexian_secret_4","Quantity":1,"TargetID":"","MinEnhance":0,"ObjectiveID":"yexian_secret_4_2"},{"Slot":"","Type":"kill","Label":"龍城女帝","__row":28,"QuestID":"yexian_secret_5","Quantity":5,"TargetID":"boss50","MinEnhance":0,"ObjectiveID":"yexian_secret_5_1"},{"Slot":"","Type":"kill","Label":"星蝕觀測者・阿斯特拉","__row":29,"QuestID":"yexian_secret_5","Quantity":1,"TargetID":"boss80","MinEnhance":0,"ObjectiveID":"yexian_secret_5_2"}]'::jsonb
 THEN RAISE EXCEPTION 'QUEST_CONDITIONS_CHANGED'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(edits)) <> 44 OR
 (SELECT count(DISTINCT p->>'DialogueID') FROM jsonb_array_elements(edits) p) <> 44 OR
 EXISTS(SELECT 1 FROM jsonb_array_elements(edits) p WHERE
   (SELECT count(*) FROM jsonb_array_elements(oldrow.data_json->'data'->'QuestDialogues') r WHERE
    r->>'DialogueID'=p->>'DialogueID' AND r->>'QuestID'=p->>'QuestID' AND r->>'Text'=p->>'before') <> 1)
 THEN RAISE EXCEPTION 'DIALOGUE_CONFLICT'; END IF;
 SELECT jsonb_agg(CASE WHEN p.value IS NULL THEN r.value ELSE r.value || jsonb_build_object('Text',p.value->'Text') END ORDER BY r.ord)
 INTO updated_dialogues FROM jsonb_array_elements(oldrow.data_json->'data'->'QuestDialogues') WITH ORDINALITY r(value,ord)
 LEFT JOIN jsonb_array_elements(edits) p(value) ON p.value->>'DialogueID'=r.value->>'DialogueID';
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(oldrow.data_json->'data'->'MistConfig') r
 JOIN jsonb_array_elements(flag_rules) f ON r->>'Key'=f->>'Key' WHERE r->'Value' <> f->'Value')
 THEN RAISE EXCEPTION 'FLAG_CONFIG_CONFLICT'; END IF;
 SELECT coalesce(jsonb_agg(r.value ORDER BY r.ord),'[]'::jsonb) INTO updated_config
 FROM jsonb_array_elements(oldrow.data_json->'data'->'MistConfig') WITH ORDINALITY r(value,ord)
 WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(flag_rules) f WHERE f->>'Key'=r.value->>'Key');
 updated_config := updated_config || flag_rules;
 next_version := to_char(stamp AT TIME ZONE 'UTC','YYYYMMDD-HH24MISS') || '-quest475-flag476';
 next_package := jsonb_set(jsonb_set(oldrow.data_json,'{data,QuestDialogues}',updated_dialogues),'{data,MistConfig}',updated_config)
 || jsonb_build_object('dataVersion',next_version,'generatedAt',stamp);
 IF (next_package->'data')-'QuestDialogues'-'MistConfig' <> (oldrow.data_json->'data')-'QuestDialogues'-'MistConfig'
 THEN RAISE EXCEPTION 'UNEXPECTED_OTHER_TABLE_CHANGE'; END IF;
 INSERT INTO public."GameDataVersions" (version,published_at,published_by,data_json)
 SELECT oldrow.version,oldrow.published_at,'quest475-flag476-prechange-backup',oldrow.data_json
 WHERE NOT EXISTS(SELECT 1 FROM public."GameDataVersions" WHERE version=oldrow.version);
 INSERT INTO public."GameDataVersions" (version,published_at,published_by,data_json)
 VALUES(next_version,stamp,'quest475-flag476-approved',next_package);
 UPDATE public."GameDataCurrent" SET version=next_version,published_at=stamp,data_json=next_package WHERE channel='production';
END $publish$;
COMMIT;
SELECT version, jsonb_array_length(data_json->'data'->'QuestDialogues') AS dialogue_count
FROM public."GameDataCurrent" WHERE channel='production';
